 51→function addTracksToPlaylist(username, playlist, tracks, start, callback) {
 52→        var maxTracksPerPlaylistAdd = 100;
 53→    var url = 'https://api.spotify.com/v1/users/' + username +
 54→        '/playlists/' + playlist +
 55→        '/tracks';
 56→
 57→    var thisTracks = tracks.slice(start, start + maxTracksPerPlaylistAdd);
 58→    var uris = { 'uris': thisTracks };
 59→
 60→    // PUT replaces all tracks, POST appends
 61→    $.ajax(url, {
 62→        type: 'POST',
 63→        data: JSON.stringify(uris),
 64→        dataType: 'json',
 65→        processData:false,
 66→        headers: {
 67→            'Authorization': 'Bearer ' + g_access_token,
 68→            'Content-Type': 'application/json'
 69→        },
 70→        success: function(r) {
 71→            if (start + maxTracksPerPlaylistAdd >= tracks.length) {
 72→                    callback(true);
 73→            } else {
 74→                showStatus(Math.round(100 * start / tracks.length)  + "% saved");
 75→                addTracksToPlaylist(username, playlist, tracks,
 76→                    start + maxTracksPerPlaylistAdd, callback);
 77→            }
 78→        },
 79→        error: function(r, status, err) {
 80→            callback(null);
 81→        }
 82→    });
 83→}
