158→function doit() {
159→    // parse hash
160→    var hash = location.hash.replace(/#/g, '');
161→    var all = hash.split('&');
162→    var maxTracks = 10;
163→    var args = {};
164→
165→    all.forEach(function(keyvalue) {
166→        var idx = keyvalue.indexOf('=');
167→        var key = keyvalue.substring(0, idx);
168→        var val = keyvalue.substring(idx + 1);
169→        args[key] = val;
170→    });
171→
172→    if (typeof(args['access_token']) != 'undefined') {
173→        // got access token
174→        g_access_token = args['access_token'];
175→    }
176→
177→    if (typeof(args['code']) != 'undefined') {
178→        // got access code
179→        g_auth_code = args['code'];
180→        console.log('auth code is', g_auth_code);
181→    }
182→
183→    g_name = localStorage.getItem('playlist-title');
184→    g_tracks = JSON.parse(localStorage.getItem('playlist-tids'));
185→    g_uri = localStorage.getItem('playlist-uri');
186→    var tracks = g_tracks;
187→
188→    if (g_uri) {
189→        var username = g_uri.split(':')[2];
190→        var pid = g_uri.split(':')[4];
191→
192→        replaceTracksInPlaylist(username, pid, tracks, function(ok) {
193→            addedTracks(ok, username, pid, g_name);
194→        });
195→
196→    } else {
197→        getUsername(function(username) {
198→            createPlaylist(username, g_name, function(playlist) {
199→                if (playlist) {
200→                    addTracksToPlaylist(username, playlist, tracks, 0, function(ok){
201→                        addedTracks(ok, username, playlist, g_name);
202→                    });
203→                } else {
204→                    $("#error").show();
205→                    $('#creating').hide();
206→                }
207→            });
208→        });
209→    }
210→}
